'Custom_SMS_Guide_Title' => 'Comment configurer',
'Custom_SMS_Guide_Intro' => 'Tout fournisseur SMS disposant d\'une API HTTP peut être connecté. Ouvrez la documentation de l\'API de votre fournisseur, copiez le point de terminaison, la méthode et les noms de champs, puis faites la correspondance ci-dessous à l\'aide des variables.',
'Custom_SMS_Guide_Placeholder_Phone' => 'le numéro de téléphone du destinataire',
'Custom_SMS_Guide_Placeholder_Message' => 'le texte du SMS',
'Custom_SMS_Guide_Placeholder_Sender' => 'l\'ID expéditeur saisi ci-dessus',
'Custom_SMS_Guide_Api_Url' => 'L\'URL complète du point de terminaison indiquée dans la documentation de votre fournisseur, par ex. https://api.provider.com/sms/send. Les variables sont également autorisées directement dans l\'URL, par ex. ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST est la méthode la plus courante. Choisissez GET uniquement si votre fournisseur attend tout dans l\'URL — les champs du corps sont alors envoyés comme paramètres de requête.',
'Custom_SMS_Guide_Content_Type' => '"json" envoie le contenu sous forme de corps JSON (application/json). "form" l\'envoie comme un formulaire HTML classique (application/x-www-form-urlencoded). Vérifiez ce qu\'attend votre fournisseur ; ce paramètre est ignoré pour GET.',
'Custom_SMS_Guide_Sender' => 'Votre ID expéditeur approuvé ou le numéro de téléphone émetteur. Il remplit uniquement la variable {sender} — pour être transmis, il doit être utilisé dans le corps, les en-têtes ou l\'URL.',
'Custom_SMS_Guide_Success_Keyword' => 'Facultatif mais recommandé. Certains fournisseurs répondent "200 OK" même lorsque l\'envoi échoue. Saisissez un mot ou un fragment qui n\'apparaît que dans une réponse réussie (par ex. success). Si la réponse ne le contient pas, le SMS est considéré comme échoué.',
'Custom_SMS_Guide_Headers' => 'En-têtes d\'authentification requis par votre fournisseur, par ex. Authorization = Bearer VOTRE_CLE_API, ou Api-Key = VOTRE_CLE_API. N\'ajoutez pas Content-Type — il est défini automatiquement.',
'Custom_SMS_Guide_Payload' => 'Les champs du corps de la requête, nommés exactement comme dans la documentation de votre fournisseur. Utilisez les variables comme valeurs, par ex. to = {phone}, message = {message}, from = {sender}.',
